INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_NOR_SUTTUNGR_PROSE_','ENT_NOR_SUTTUNGR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','When the giant Suttung, the son of Gilling, found this out he came and seized the dwarfs, took them out to sea and left them on a rocky island, which was flooded at high tide. They prayed Suttung to spare their lives, and offered him in atonement for their father''s blood the precious mead, which he accepted. Suttung brought the mead home with him, and hid it in a place called Hnitbjorg. He set his daughter Gunlad to guard it.','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_KVASIR_PROSE_','ENT_NOR_KVASIR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','For these reasons we call songship Kvasir''s blood; the drink of the dwarfs; the dwarfs'' fill; some kind of liquor of Odrarer, or Bodn or Son; the ship of the dwarfs (because this mead ransomed their lives from the rocky isle); the mead of Suttung, or the liquor of Hnitbjorg. 5.','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_FOLKVANGR_PROSE_','ENT_NORR_FOLKVANGR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','She has in heaven a dwelling which is called Folkvang, and when she rides to the battle, one half of the slain belong to her, and the other half to Odin. As is here said: Folkvang it is called, And there rules Freyja. For the seats in the hall Half of the slain She chooses each day; The other half is Odin''s. Her hall is Sesrymner, and it is large and beautiful. When she goes abroad, she drives in a car drawn by two cats.','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_SVARTALFHEIM_PROSE_','ENT_NORR_SVARTALFHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','So Alfather sent the youth, who is called Skirner, and is Frey''s messenger, to some dwarfs in Svartalfheim, and had them make the fetter which is called Gleipner. It was made of six things: of the footfalls of cats, of the beard of women, of the roots of the mountain, of the sinews of the bear, of the breath of the fish, and of the spittle of the birds.','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THRUD_PROSE_','ENT_NOR_THRUD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','Thus they are named in Grimner''s Lay: Hrist and Mist I want my horn to bring to me; Skeggold and Skogul, THE PROSE EDDA Chapter 10: The Goddesses (Asynjes) 34 Hild and Thrud, Hlok and Herfjoter, Gol and Geirahod, Randgrid and Radgrid, And Reginleif; These bear ale to the einherjes. These are called valkyries. Odin sends them to all battles, where they choose those who are to be slain, and rule over the victory.','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GEIRROD_GIANT_PROSE_','ENT_NOR_GEIRROD_GIANT','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Faulkes)','Snorri Sturluson, Prose Edda (Faulkes)','He is also called Hangagod, Haptagod, Farmagod; and he gave himself still more names when he came to King Geirrod: Grim is my name, And Ganglare, Herjan, Hjalmbore, Thek, Thride, Thud, Ud, Helblinde, Har Sad, Svipal, Sangetal, Herteit, Hnikar, Biley g, Baleyg, Bolverk, Fjolner, Grimner, Glapsvid, Fjolsvid, Sidhot, Sidskeg, Sigfather, Hnikud, THE PROSE EDDA Chapter 8: The Asas 28 Alfather, Atrid, Farmatyr, Oske, Ome, Jafnhar, Biflinde, Gondler, Harbard, Svi','Anthony Faulkes',1987,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
